/**
 * Ghost fibers shader.
 *
 * ## The mathematical idea
 *
 * Twelve fibers, each a curve `y = base + amplitude x sin(x x frequency
 * + phase)` whose seed fixes the amplitude, the frequency and the drift. The
 * fragment does not walk the curve: it compares its ordinate with the
 * fiber's at the same abscissa, which suffices as long as the fibers stay
 * close to the horizontal.
 *
 * The attraction is an interpolation, not a force: level with the pointer,
 * the fiber's ordinate is pulled towards its own by a fraction equal to a
 * gaussian of the gap in abscissa. The fiber therefore pinches around the
 * cursor and recovers its path further on, without discontinuity.
 *
 * Each fiber is painted twice: a very fine core, and a broad haze doubling
 * it. It is that pairing that makes it a ghost — a stroke alone would be a
 * hair, a haze alone a cloud.
 *
 * ## Uniforms
 *
 * - `uTime` — time in seconds, supplied by the engine.
 * - `uResolution` — canvas size in pixels, supplied by the engine.
 * - `uColorA` — the background.
 * - `uColorB` — the fibers at rest.
 * - `uColorC` — the fibers pulled towards the pointer.
 * - `uPointer` — damped pointer position, in texture coordinates.
 * - `uFibers` — number of fibers, capped at twelve.
 * - `uBend` — strength of the attraction, between zero and one.
 * - `uSpeed` — drift speed of the fibers.
 */
export const GHOST_FIBERS_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform vec2 uPointer;
uniform float uFibers;
uniform float uBend;
uniform float uSpeed;

// A fiber's seed, stable from one frame to the next.
float fiberSeed(float index) {
  return fract(sin(index * 91.37) * 47453.19);
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 p = vUv * vec2(aspect, 1.0);
  vec2 m = uPointer * vec2(aspect, 1.0);

  float count = clamp(uFibers, 1.0, 12.0);
  float veil = 0.0;
  float pulled = 0.0;

  // Constant bound: the language specification demands it. The fibers beyond
  // the setting are cancelled by a mask rather than by a loop exit, which
  // older platforms refuse.
  for (int i = 0; i < 12; i += 1) {
    float index = float(i);
    float used = step(index, count - 0.5);

    float seed = fiberSeed(index + 1.0);
    float base = (index + 0.5) / count;
    float amplitude = 0.04 + seed * 0.10;
    float frequency = 1.6 + seed * 3.4;
    float phase = seed * 6.2831853 + uTime * uSpeed * (0.4 + seed * 0.7);

    float y = base + amplitude * sin(p.x * frequency + phase);

    // The pointer's grip: a gaussian of the gap in abscissa.
    float dx = (p.x - m.x) / (0.32 * aspect);
    float grip = exp(-dx * dx) * clamp(uBend, 0.0, 1.0);
    y = mix(y, m.y, grip * 0.9);

    float d = p.y - y;
    float core = exp(-d * d * 9000.0);
    float haze = exp(-d * d * 260.0);
    float strand = used * (core * 0.85 + haze * 0.30);

    veil += strand;
    pulled += strand * grip;
  }

  vec3 colour = mix(uColorA, uColorB, clamp(veil, 0.0, 1.0));
  colour = mix(colour, uColorC, clamp(pulled, 0.0, 1.0) * 0.9);

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Ghost fibers: filaments that drift across the frame and pinch towards
 * the pointer when it passes beneath them.
 *
 * ## What this background reacts to
 *
 * To pointer movement, with damping: level with the cursor, the fibers are
 * pulled towards its ordinate, the more so the closer they are to it in
 * abscissa. The pinch is an interpolation, not a force: the fibers recover
 * their path as soon as the cursor moves away, with no spring and no
 * memory. On leaving the frame, the hook brings the target back to the
 * centre.
 *
 * What sets this entry apart from `strands`: there the locks are anchored at
 * the bottom of the frame and sway, with no pointer. From `threads`: there
 * the bundle is fixed and of constant thickness. And from `web-threads`:
 * that is a web of joined points, in a 3D scene.
 *
 * ## The pointer → shader bridge
 *
 * No React render per frame: the component mutates a stable array in place
 * passed as a uniform, and the surface re-reads its uniforms every frame. The
 * copy happens inside the engine loop, at input priority.
 *
 * ## Under reduced motion
 *
 * The surface is refused by the engine and the static fallback shows: the
 * pointer tracking is a nicety, not content.
 *
 * @module
 */

import {
  CLOCK_PRIORITY,
  clock,
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { useEffect, useRef, useState, type ReactElement } from 'react'

import { usePointerDamped } from '@registre/hooks/usePointerDamped'

import { GHOST_FIBERS_FRAGMENT } from './ghost-fibers.shader.js'

/** What the escape hatch receives. */
export interface GhostFibersControls {
  /** Colours actually handed to the shader. */
  readonly colours: readonly ShaderColour[]
  /** Reason for the refusal, if there is one. */
  readonly refused: string | undefined
}

/** Properties specific to this component. */
export interface GhostFibersOwnProps {
  /** Number of fibers. Capped at twelve by the shader. @defaultValue 9 */
  fibers?: number
  /** Strength of the attraction towards the pointer, between zero and one. @defaultValue 0.7 */
  bend?: number
  /** Drift speed of the fibers. @defaultValue 0.6 */
  speed?: number
  /** Tokens whose colours are read. */
  colors?: readonly string[]
  /** Fallback classes. */
  fallback?: string
  /** Escape hatch. */
  onReady?: ReadyCallback<GhostFibersControls>
}

/** Every property. */
export type GhostFibersProps = Customisable<GhostFibersOwnProps>

/** Tokens used by default: the background, the fibers at rest, the pulled fibers. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-theme-muted',
  '--o-palette-cyan-300',
] as const

/** Default fallback: a frozen hue, in the same tones. */
const DEFAULT_FALLBACK =
  'o-bg-gradient-to-b o-from-zinc-50 dark:o-from-zinc-950 o-via-cyan-100 dark:o-via-cyan-950 o-to-zinc-50 dark:o-to-zinc-950'

/**
 * Ghost fibers.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <GhostFibers className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function GhostFibers({
  fibers = 9,
  bend = 0.7,
  speed = 0.6,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: GhostFibersProps): ReactElement {
  const [host, setHost] = useState<HTMLDivElement | null>(null)

  // Stable array, mutated in place: the surface re-reads the uniforms every
  // frame, the identity never changes, mutating is enough — no setState.
  const uPointer = useRef<number[]>([0.5, 0.5]).current

  const pointer = usePointerDamped({ host, speed: 3.5, name: 'ghost-fibers : pointer' })

  useEffect(() => {
    const subscription = clock.subscribe(
      () => {
        // From the hook's frame (centred, y downwards) to the texture's frame
        // (bottom-left corner, y upwards).
        uPointer[0] = (pointer.current.x + 1) / 2
        uPointer[1] = 1 - (pointer.current.y + 1) / 2
      },
      { priority: CLOCK_PRIORITY.input, name: 'ghost-fibers : bridge' },
    )
    return () => subscription.unsubscribe()
  }, [pointer, uPointer])

  const {
    ref,
    setHost: setShaderHost,
    ready,
    refused,
    colours,
  } = useTokenShader<HTMLDivElement>({
    fragment: GHOST_FIBERS_FRAGMENT,
    colors,
    uniforms: { uPointer, uFibers: fibers, uBend: bend, uSpeed: speed },
    name: 'ghost-fibers',
    // Each fiber costs two exponentials per fragment: it is the only lever
    // that counts, and it is set by the count.
    degrade: (quality) => ({
      uFibers: quality === 'low' ? Math.min(fibers, 5) : fibers,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        setShaderHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
